//! Puerto's runtime core: the domain types every project generated by
//! [Puerto](https://github.com/Guuri11/Puerto) shares, whatever its entities and adapters — paged
//! lists, the repository error, domain events with the ports their transports implement, and the
//! mail ports, and the auth port.
//!
//! No driver, no runtime, no I/O: a project's domain layer depends on it (ADR-0017, ADR-0018).

pub mod auth;
pub mod correo;
pub mod error_repositorio;
pub mod eventos;
pub mod paginacion;

pub use auth::{Autenticador, ErrorAuth, Principal};
pub use error_repositorio::ErrorRepositorio;
pub use eventos::{
    ErrorDecodificacion, EventoDominio, ManejadorEvento, ResultadoManejo, SobreEvento,
};
pub use paginacion::{
    LIMITE_PAGINA_MAXIMO, LIMITE_PAGINA_POR_DEFECTO, Pagina, PeticionPagina, todas_las_paginas,
};
